/* Cloudflare Pages Function — progress storage in Workers KV.
 *   GET /api/progress/:id  → stored JSON (204 if none yet)
 *   PUT /api/progress/:id  → replace stored JSON
 * Requires a KV namespace bound as PROGRESS (see wrangler.toml / README).
 * The id is a random, unguessable sync code generated by the client.
 */
const ID_RE = /^[a-z0-9]{16,64}$/;
const MAX_BYTES = 256 * 1024;
// Inactive profiles expire after a year (refreshed on every save).
const TTL_SECONDS = 365 * 24 * 3600;

const json = (body, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json", "cache-control": "no-store" },
  });

function guard(env, id) {
  if (!env.PROGRESS) return json({ error: "sync-not-configured" }, 503);
  if (!ID_RE.test(id)) return json({ error: "bad-id" }, 400);
  return null;
}

export async function onRequestGet({ params, env }) {
  const bad = guard(env, params.id);
  if (bad) return bad;
  const value = await env.PROGRESS.get("p:" + params.id);
  // 204 rather than 404 so first visits don't log a console error.
  if (!value) return new Response(null, { status: 204, headers: { "cache-control": "no-store" } });
  return new Response(value, {
    headers: { "content-type": "application/json", "cache-control": "no-store" },
  });
}

export async function onRequestPut({ params, env, request }) {
  const bad = guard(env, params.id);
  if (bad) return bad;
  if (Number(request.headers.get("content-length") || 0) > MAX_BYTES)
    return json({ error: "too-large" }, 413);
  const text = await request.text();
  if (text.length > MAX_BYTES) return json({ error: "too-large" }, 413);

  let data;
  try {
    data = JSON.parse(text);
  } catch {
    return json({ error: "bad-json" }, 400);
  }
  const isObj = (x) => x && typeof x === "object" && !Array.isArray(x);
  if (data?.v !== 1 || !isObj(data.items) || !isObj(data.lessons) || !isObj(data.days))
    return json({ error: "bad-shape" }, 400);

  await env.PROGRESS.put("p:" + params.id, text, { expirationTtl: TTL_SECONDS });
  return json({ ok: true, updatedAt: data.updatedAt });
}
